            && self.unconditional_relationship_directions.as_slice() == [(3, Direction::Incoming)]
            && self.unqualified_node_merge_command_counts.as_slice() == [1]
            && self.exact_ordered_overlay_relationships
            && self.node_merge_count == 1
            && self.merge_count == 0
            && self.delete_count == 0
