    /// Records only the empty-scope `WITH *` boundary after the first MATCH/CREATE pair in
    /// Create3 [2]/[3]. Star carries no entity or value binding in these anonymous programs, but
    /// its lexical position still matters: recording the exact two-command prefix prevents this
    /// no-op boundary from becoming a general Star projection capability.
    fn compile_exact_empty_scope_star_boundary(&mut self, projection: &Projection) -> bool {
        if self.empty_scope_star_boundary_command_count.is_some()
            || self.path.is_some()
            || !self.alias_boundaries.is_empty()
            || self.node_merge_count != 0
            || self.merge_count != 0
            || self.delete_count != 0
            || !self.stream.scope.is_empty()
            || !self.stream.input_variables.is_empty()
            || !self.stream.input_keys.is_empty()
            || !self.stream.property_names.is_empty()
            || !self.stream.label_names.is_empty()
            || !self.stream.relationship_type_names.is_empty()
            || self.stream.relationship_commands != 0
            || self.stream.entity_slot_count != 2
            || !matches!(
                projection,
                Projection {
                    distinct: false,
                    items,
                } if matches!(
                    items.as_slice(),
                    [ProjectionItem {
                        expression: Expression::Star,
                        alias: None,
                        ..
                    }]
                )
            )
            || !matches!(
                (self.stream.commands.as_slice(), self.commands.as_slice()),
                (
                    [
                        ResidentRowCreateCommand::MatchNode(matched),
                        ResidentRowCreateCommand::CreateNode(created),
                    ],
                    [
                        ResidentRowBoundRelationshipCommand::MatchNode { properties },
                        ResidentRowBoundRelationshipCommand::CreateNode,
                    ],
                ) if matched.output_entity == 0
                    && matched.labels.is_empty()
                    && properties.is_empty()
                    && created.output_entity == 1
                    && created.labels.is_empty()
                    && created.properties.is_empty()
            )
        {
            return false;
        }
        self.empty_scope_star_boundary_command_count = Some(2);
        true
    }

