    fn compile_resident_query(
        query: &str,
        graph: &GraphStore,
    ) -> Result<Option<super::CompiledResidentPlan>> {
        let parsed = crate::cypher::parse(query)?;
        let bound = crate::cypher::bind(parsed, graph.catalog(), BindCapabilities::default())?;
        let plan = crate::cypher::plan(bound)?;
        compile(
            &plan,
            ProjectId(uuid::Uuid::nil()),
            graph.catalog(),
            graph,
            None,
            &BTreeMap::new(),
            graph.revision(),
            16,
        )
    }

    fn compile_mutation_query(
        query: &str,
        graph: &GraphStore,
    ) -> Result<Option<super::CompiledResidentMutationPlan>> {
        let parsed = crate::cypher::parse(query)?;
        let bound = crate::cypher::bind(
            parsed,
            graph.catalog(),
            BindCapabilities {
                write: true,
                ..BindCapabilities::default()
            },
        )?;
        let plan = crate::cypher::plan(bound)?;
        compile_mutation(
            &plan,
            ProjectId(uuid::Uuid::nil()),
            graph.catalog(),
            graph,
            &BTreeMap::new(),
            Bookmark { term: 0, index: 1 },
            ResidentExecutionId { high: 19, low: 23 },
            16,
        )
    }

    #[test]
    fn selective_integer_start_filter_precedes_resident_expansion() -> Result<()> {
        let mut graph = GraphStore::default();
        let label = graph.catalog_mut().intern_label("Node")?;
        let property = graph.catalog_mut().intern_property("value")?;
        let relationship = graph.catalog_mut().intern_relationship_type("R")?;
        for (id, value) in [(1_u64, 42_i64), (2, 7)] {
            graph.insert_node(NodeInput {
                id: NodeId(id),
                layer: Layer::Observed,
                revision: graph.revision().saturating_add(1),
                labels: vec![label],
                properties: vec![(property, ScalarValue::Integer(value))],
            })?;
        }
        graph.insert_edge(EdgeInput {
            id: EdgeId(1),
            source: NodeId(1),
            target: NodeId(2),
            relationship_type: relationship,
            layer: Layer::Observed,
            revision: graph.revision().saturating_add(1),
            properties: Vec::new(),
        })?;

        let compiled = compile_resident_query(
            "MATCH (n:Node)-[:R]->(m) WHERE n.value = 42 RETURN count(m)",
            &graph,
        )?
        .ok_or_else(|| Error::internal("selective traversal was not resident-compiled"))?;
        assert!(compiled.request.property_filters.is_empty());
        assert!(matches!(
            compiled.request.predicates.as_slice(),
            [predicate]
                if predicate.binding == ResidentNodeBinding::Start
                    && predicate.property == property
                    && predicate.operation == CompareOp::Eq
                    && predicate.operand == 42
        ));
        Ok(())
    }

    #[test]
    fn match_create_delete_uses_one_statement_local_row_mutation_schedule() -> Result<()> {
        let mut graph = GraphStore::default();
        graph.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: Vec::new(),
        })?;
        let parsed = crate::cypher::parse("MATCH () CREATE (n) DELETE n")?;
        let bound = crate::cypher::bind(
            parsed,
            graph.catalog(),
            BindCapabilities {
                write: true,
                ..BindCapabilities::default()
            },
        )?;
        let plan = crate::cypher::plan(bound)?;
        let compiled = compile_row_mutation(
            &plan,
            ProjectId(uuid::Uuid::nil()),
            graph.catalog(),
            &graph,
            &BTreeMap::new(),
            Bookmark {
                term: 0,
                index: graph.revision(),
            },
            ResidentExecutionId { high: 41, low: 43 },
            2,
            1,
            16,
        )?
        .ok_or_else(|| crate::Error::internal("MATCH/CREATE/DELETE was not admitted"))?;
        compiled.request.validate()?;
        let body = compiled
            .request
            .bound_relationship_merge_body()
            .ok_or_else(|| crate::Error::internal("MATCH/CREATE/DELETE chose the wrong body"))?;
        assert!(matches!(
            (body.program.commands.as_slice(), body.commands.as_slice()),
            (
                [
                    ResidentRowCreateCommand::MatchNode(_),
                    ResidentRowCreateCommand::CreateNode(_),
                ],
                [
                    ResidentRowBoundRelationshipCommand::MatchNode { .. },
                    ResidentRowBoundRelationshipCommand::CreateNode,
                ],
            )
        ));
        assert!(matches!(
            body.schedule.stages.as_slice(),
            [
                ResidentRowBoundRelationshipStage::Command { command: 0 },
                ResidentRowBoundRelationshipStage::Command { command: 1 },
                ResidentRowBoundRelationshipStage::Delete {
                    detach: false,
                    targets,
                    ..
                },
            ] if matches!(targets.as_slice(), [target] if target.entity == 1)
        ));
        assert!(body.outputs.is_empty());

        let mut cpu = CpuBackend::new(32 * 1024 * 1024, 1024 * 1024);
        cpu.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let result = cpu.execute_row_mutation(&compiled.request, &CancellationToken::new())?;
        let validated = result.validate_for_publication(&compiled.request, BackendKind::Cpu)?;
        let validated = validated.bound_relationship_merge().ok_or_else(|| {
            crate::Error::internal("MATCH/CREATE/DELETE validated as the wrong mutation body")
        })?;
        assert_eq!(validated.intents().len(), 1);
        assert_eq!(validated.delete_intents().len(), 1);
        assert_eq!(validated.delete_intents()[0].entity.kind, EntityKind::Node);
        assert!(validated.delete_intents()[0].entity.dense_row.is_none());
        assert!(validated.delete_intents()[0].entity.created_by.is_some());
        Ok(())
    }

    fn literal_map_graph(properties: &[(&str, ScalarValue)]) -> Result<GraphStore> {
        let mut graph = GraphStore::default();
        let label = graph.catalog_mut().intern_label("X")?;
        let mut resident_properties = Vec::with_capacity(properties.len());
        for (name, value) in properties {
            let property = graph.catalog_mut().intern_property(name)?;
            resident_properties.push((property, value.clone()));
        }
        graph.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: vec![label],
            properties: resident_properties,
        })?;
        Ok(graph)
    }

    fn compile_segmented_query(
        query: &str,
        graph: &GraphStore,
    ) -> Result<Option<super::CompiledResidentSegmentedAggregationPlan>> {
        let parameters = BTreeMap::new();
        let physical = optimized_segmented_plan(query, graph, &parameters)?;
        compile_segmented_aggregation(
            &physical,
            ProjectId(uuid::Uuid::nil()),
            graph,
            &parameters,
            Bookmark {
                term: 0,
                index: graph.revision(),
            },
            ResidentExecutionId { high: 17, low: 29 },
            64,
        )
    }

    fn optimized_segmented_plan(
        query: &str,
        graph: &GraphStore,
        parameters: &BTreeMap<String, ResultValue>,
    ) -> Result<crate::cypher::PhysicalPlan> {
        let parsed = crate::cypher::parse(query)?;
        let bound = crate::cypher::bind(parsed, graph.catalog(), BindCapabilities::default())?;
        let physical = crate::cypher::plan(bound)?;
        let statistics = StatisticsSnapshot::collect(graph);
        let (physical, _) = optimize(
            physical,
            OptimizerInput {
                statistics: &statistics,
                catalog: graph.catalog(),
                indexes: None,
                parameters,
                backend: BackendKind::Metal,
                scratch_budget_bytes: 64 * 1024 * 1024,
                max_result_rows: 64,
                runtime_feedback: None,
                allow_runtime_checkpoint: true,
            },
        );
        Ok(physical)
    }

    #[test]
    fn list11_3_range_direction_proof_is_one_sealed_cpu_program() -> Result<()> {
        let graph = GraphStore::default();
        let compiled = compile_segmented_query(
            "WITH 0 AS start, [1, 2, 500, 1000, 1500] AS stopList, [-1000, -3, -2, -1, 1, 2, 3, 1000] AS stepList\n\
             UNWIND stopList AS stop\n\
             UNWIND stepList AS step\n\
             WITH start, stop, step, range(start, stop, step) AS list\n\
             WITH start, stop, step, list, sign(stop-start) <> sign(step) AS empty\n\
             RETURN ALL(ok IN collect((size(list) = 0) = empty) WHERE ok) AS okay",
            &graph,
        )?
        .ok_or_else(|| crate::Error::internal("List11 [3] was not admitted"))?;
        let program = compiled
            .request
            .program
            .as_ref()
            .ok_or_else(|| crate::Error::internal("List11 [3] omitted its sealed program"))?;
        assert_eq!(program.maximum_intermediate_rows, 40);
        assert_eq!(program.maximum_list_items, 8);
        assert!(matches!(
            program.stages.as_slice(),
            [
                ResidentSegmentedAggregationStage {
                    operation: ResidentSegmentedAggregationOperation::Project { .. },
                    ..
                },
                ResidentSegmentedAggregationStage {
                    operation: ResidentSegmentedAggregationOperation::Unwind { .. },
                    ..
                },
                ResidentSegmentedAggregationStage {
                    operation: ResidentSegmentedAggregationOperation::Unwind { .. },
                    ..
                },
                ResidentSegmentedAggregationStage {
                    operation: ResidentSegmentedAggregationOperation::Aggregate { .. },
                    ..
                },
                ResidentSegmentedAggregationStage {
                    operation: ResidentSegmentedAggregationOperation::Project { .. },
                    ..
                },
                ResidentSegmentedAggregationStage {
                    operation: ResidentSegmentedAggregationOperation::Order { .. },
                    ..
                },
                ResidentSegmentedAggregationStage {
                    operation: ResidentSegmentedAggregationOperation::Project { .. },
                    ..
                },
            ]
        ));

        let mut cpu = CpuBackend::new(32 * 1024 * 1024, 1024 * 1024);
        cpu.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let result =
            cpu.execute_segmented_aggregation(&compiled.request, &CancellationToken::new())?;
        let published = result.validate_for_publication(&compiled.request, BackendKind::Cpu)?;
        let relation = published.relation();
        assert_eq!((relation.row_count, relation.column_count), (1, 1));
        assert!(matches!(
            relation.cells.as_slice(),
            [cell]
                if cell.tag == ResidentSegmentedValueTag::Boolean && cell.payload == 1
        ));
        Ok(())
    }

    #[test]
    fn with_order_temporal_consistency_compiler_preserves_raw_inputs_and_fails_closed() -> Result<()>
    {
        let graph = GraphStore::default();
        let parameters = BTreeMap::new();
        let query = |source: &str| {
            format!(
                "{source}\n\
                 WITH values, size(values) AS numOfValues\n\
                 UNWIND values AS value\n\
                 WITH size([x IN values WHERE x < value]) AS x, value, numOfValues\n\
                   ORDER BY value\n\
                 WITH numOfValues, collect(x) AS orderedX\n\
                 RETURN orderedX = range(0, numOfValues-1) AS equal"
            )
        };
        let compile_exact = |query: &str| {
            let physical = optimized_segmented_plan(query, &graph, &parameters)?;
            super::compile_segmented_unit_scalar_consistency(
                &physical,
                ProjectId(uuid::Uuid::nil()),
                &graph,
                &parameters,
                Bookmark { term: 0, index: 0 },
                ResidentExecutionId { high: 17, low: 29 },
                64,
            )
        };

        let compiled = compile_exact(&query(
            "WITH [date({year: 1984, month: 10, day: 11}), date('1985-05-06')] AS values",
        ))?
        .ok_or_else(|| {
            crate::Error::internal("raw map/String temporal consistency plan was not admitted")
        })?;
        let program = compiled.request.program.as_ref().ok_or_else(|| {
            crate::Error::internal("temporal consistency plan omitted its program")
        })?;
        let crate::execution::ResidentSegmentedAggregationSource::Unit {
            prelude:
                crate::execution::ResidentSegmentedUnitPrelude::RawTemporalList {
                    program: temporal,
                    output,
                },
            ..
        } = &program.source
        else {
            return Err(crate::Error::internal(
                "temporal consistency plan omitted its raw Unit prelude",
            ));
        };
        assert_eq!(temporal.output_registers, [0, 1]);
        assert!(matches!(
            temporal.invocations.as_slice(),
            [
                crate::execution::ResidentTemporalValueInvocation {
                    function: crate::execution::ResidentTemporalValueFunction::Date,
                    input: crate::execution::ResidentTemporalValueInput::Map(_),
                },
                crate::execution::ResidentTemporalValueInvocation {
                    function: crate::execution::ResidentTemporalValueFunction::Date,
                    input: crate::execution::ResidentTemporalValueInput::String(value),
                },
            ] if value == "1985-05-06"
        ));
        let Some(crate::execution::ResidentSegmentedAggregationStage {
            operation:
                crate::execution::ResidentSegmentedAggregationOperation::Project { bindings, .. },
            ..
        }) = program.stages.first()
        else {
            return Err(crate::Error::internal(
                "temporal consistency plan omitted stage zero",
            ));
        };
        assert!(matches!(
            bindings.as_slice(),
            [crate::execution::ResidentQuantifierProjection {
                output: projected,
                expression: crate::execution::ResidentQuantifierExpression::Slot(source),
            }] if projected == output && source == output
        ));

        for source in [
            // Families may not be mixed in one typed Unit list.
            "WITH [date({year: 1984}), localtime({hour: 12})] AS values",
            // Duration is deliberately outside the ordered temporal Unit contract.
            "WITH [duration({days: 1}), duration({days: 2})] AS values",
            // Scalar and raw-temporal elements may not share this homogeneous route.
            "WITH [date({year: 1984}), 1985] AS values",
            // Parameters, zero-argument clocks, and nested constructors are not raw packets.
            "WITH [date($value), date($value)] AS values",
            "WITH [date(), date()] AS values",
            "WITH [date(datetime({year: 1984})), date(datetime({year: 1985}))] AS values",
            // An alias boundary would require another native source/dataflow proof.
            "WITH date({year: 1984}) AS first WITH [first, first] AS values",
        ] {
            assert!(
                compile_exact(&query(source))?.is_none(),
                "temporal consistency near miss was admitted: {source}"
            );
        }
        Ok(())
    }

    #[test]
    fn aggregation6_percentile_compiler_preserves_parameter_bits_and_float_source() -> Result<()> {
        let mut graph = GraphStore::default();
        let price = graph.catalog_mut().intern_property("price")?;
        for (id, value) in [(1, 10.0), (2, 20.0), (3, 30.0)] {
            graph.insert_node(NodeInput {
                id: NodeId(id),
                layer: Layer::Observed,
                revision: id,
                labels: Vec::new(),
                properties: vec![(price, ScalarValue::Float(value.into()))],
            })?;
        }
        let percentile = -0.0_f64;
        let parameters = BTreeMap::from([(
            "percentile".to_owned(),
            ResultValue::Scalar(ScalarValue::Float(percentile.into())),
        )]);
        let physical = optimized_segmented_plan(
            "MATCH (n) RETURN percentileDisc(n.price, $percentile) AS p",
            &graph,
            &parameters,
        )?;
        let compiled = compile_segmented_aggregation(
            &physical,
            ProjectId(uuid::Uuid::nil()),
            &graph,
            &parameters,
            Bookmark {
                term: 0,
                index: graph.revision(),
            },
            ResidentExecutionId { high: 17, low: 29 },
            64,
        )?
        .ok_or_else(|| {
            crate::Error::internal(format!(
                "Aggregation6 percentile plan was not admitted: {:#?}",
                physical.operators
            ))
        })?;
        let [descriptor] = compiled.request.aggregates.as_slice() else {
            return Err(crate::Error::internal(
                "Aggregation6 percentile descriptor arity changed",
            ));
        };
        assert_eq!(descriptor.percentile, Some(percentile.to_bits()));
        let program =
            compiled.request.program.as_ref().ok_or_else(|| {
                crate::Error::internal("Aggregation6 percentile omitted its program")
            })?;
        let reduction = program
            .stages
            .iter()
            .find_map(|stage| match &stage.operation {
                ResidentSegmentedAggregationOperation::Aggregate { reductions, .. } => {
                    reductions.first()
                }
                _ => None,
            })
            .ok_or_else(|| crate::Error::internal("Aggregation6 percentile omitted reduction"))?;
        assert_eq!(reduction.percentile, descriptor.percentile);
        Ok(())
    }

    #[test]
    fn return6_18_erases_only_the_exact_alias_boundary() -> Result<()> {
        let graph = GraphStore::default();
        let query = "MATCH (me: Person)--(you: Person) \
                     WITH me.age AS age, you \
                     RETURN age, age + count(you.age)";
        let parameters = BTreeMap::new();
        let physical = optimized_segmented_plan(query, &graph, &parameters)?;
        let aggregate_index = physical.operators.len() - 1;
        let rewritten =
            super::erase_segmented_graph_preaggregate_alias_boundary(&physical, aggregate_index)
                .ok_or_else(|| {
                    crate::Error::internal("Return6 [18] alias boundary was not erased")
                })?;
        assert_eq!(rewritten.project, physical.project);
        assert_eq!(rewritten.read_layers, physical.read_layers);
        assert_eq!(rewritten.write_layer, physical.write_layer);
        assert_eq!(rewritten.at_time, physical.at_time);
        assert_eq!(rewritten.unions, physical.unions);
        assert_eq!(rewritten.read_only, physical.read_only);
        assert_eq!(rewritten.dependencies, physical.dependencies);
        assert_eq!(rewritten.operators.len() + 1, physical.operators.len());
        let Some(crate::cypher::PhysicalOperator::Project {
            keep_scope: false,
            projection,
        }) = rewritten.operators.last()
        else {
            return Err(crate::Error::internal(
                "Return6 [18] rewrite lost its aggregate projection",
            ));
        };
        assert_eq!(projection.items[0].column_name(0), "age");
        assert_eq!(projection.items[1].column_name(1), "age + count(you.age)");
        assert!(matches!(
            &projection.items[0].expression,
            Expression::Property(source, property)
                if property == "age"
                    && matches!(source.as_ref(), Expression::Variable(variable) if variable == "me")
        ));
        assert!(compile_segmented_query(query, &graph)?.is_some());
        Ok(())
    }

    #[test]
    fn return4_11_map_property_rewrite_rejects_a_direct_sort_use() -> Result<()> {
        let graph = GraphStore::default();
        let parameters = BTreeMap::new();
        let mut physical = optimized_segmented_plan(
            "MATCH (n) \
             WITH head(collect({value: n.value})) AS latest \
             RETURN latest.value AS value ORDER BY value",
            &graph,
            &parameters,
        )?;
        let aggregate_index = physical
            .operators
            .iter()
            .position(|operator| {
                matches!(
                    operator,
                    PhysicalOperator::Project { projection, .. }
                        if projection.items.iter().any(|item| item.alias.as_deref() == Some("latest"))
                )
            })
            .ok_or_else(|| crate::Error::internal("Return4 [11] aggregate projection vanished"))?;
        let sort = physical.operators[aggregate_index + 1..]
            .iter_mut()
            .find_map(|operator| match operator {
                PhysicalOperator::Sort(items) => items.first_mut(),
                _ => None,
            })
            .ok_or_else(|| crate::Error::internal("Return4 [11] final sort vanished"))?;
        sort.expression = Expression::Property(
            Box::new(Expression::Variable("latest".to_owned())),
            "value".to_owned(),
        );

        assert!(
            super::canonicalize_segmented_graph_head_collect_map_property(&physical).is_none(),
            "a property lookup left in Sort must make the scalarizing rewrite fail closed"
        );
        Ok(())
    }

