    #[test]
    fn aggregate_filter_scope_materialization_fails_closed_without_exact_trim() -> Result<()> {
        let graph = GraphStore::default();
        let parameters = BTreeMap::new();
        let query = "MATCH (a)-->() WITH a, count(*) AS relCount WHERE relCount > 1 RETURN a";
        let physical = optimized_segmented_plan(query, &graph, &parameters)?;
        let filter_index = physical
            .operators
            .iter()
            .position(|operator| matches!(operator, crate::cypher::PhysicalOperator::Filter(_)))
            .ok_or_else(|| crate::Error::internal("WithWhere6 [1] plan omitted its filter"))?;

        let compile = |physical: &crate::cypher::PhysicalPlan| {
            compile_segmented_aggregation(
                physical,
                ProjectId(uuid::Uuid::nil()),
                &graph,
                &parameters,
                Bookmark {
                    term: 0,
                    index: graph.revision(),
                },
                ResidentExecutionId { high: 17, low: 29 },
                64,
            )
        };

        let mut hidden_filter = physical.clone();
        hidden_filter.operators[filter_index] = crate::cypher::PhysicalOperator::Filter(
            Expression::Variable("hidden_input".to_owned()),
        );
        assert!(
            compile(&hidden_filter)?.is_none(),
            "an incoming-only predicate crossed the aggregate scope boundary"
        );

        let trim_index = filter_index.saturating_add(1);
        let mut retained_scope = physical.clone();
        let crate::cypher::PhysicalOperator::Project { keep_scope, .. } =
            &mut retained_scope.operators[trim_index]
        else {
            return Err(crate::Error::internal(
                "WithWhere6 [1] plan omitted its scope trim",
            ));
        };
        *keep_scope = true;
        assert!(
            compile(&retained_scope)?.is_none(),
            "a scope-preserving aggregate filter without an exact trim was admitted"
        );
        Ok(())
    }

    #[test]
    fn return_orderby4_01_executes_static_index_unwinds_and_order_on_cpu() -> Result<()> {
        let graph = GraphStore::default();
        let query = "WITH [0, 1] AS prows, [[2], [3, 4]] AS qrows \
                     UNWIND prows AS p \
                     UNWIND qrows[p] AS q \
                     WITH p, count(q) AS rng \
                     RETURN p \
                     ORDER BY rng";
        let compiled = compile_segmented_query(query, &graph)?.ok_or_else(|| {
            crate::Error::internal("ReturnOrderBy4 [1] static index aggregation was not admitted")
        })?;
        assert_eq!(compiled.request.input.row_count, 0);
        assert!(compiled.request.input.cells.is_empty());
        let program = compiled.request.program.as_ref().ok_or_else(|| {
            crate::Error::internal("ReturnOrderBy4 [1] omitted its sealed program")
        })?;
        assert!(matches!(
            program.source,
            crate::execution::ResidentSegmentedAggregationSource::Unit { .. }
        ));
        assert!(matches!(
            program.stages.as_slice(),
            [
                crate::execution::ResidentSegmentedAggregationStage {
                    operation: crate::execution::ResidentSegmentedAggregationOperation::Project { .. },
                    ..
                },
                crate::execution::ResidentSegmentedAggregationStage {
                    operation: crate::execution::ResidentSegmentedAggregationOperation::Unwind { .. },
                    ..
                },
                crate::execution::ResidentSegmentedAggregationStage {
                    operation: crate::execution::ResidentSegmentedAggregationOperation::Unwind {
                        expression: crate::execution::ResidentQuantifierExpression::Case { .. },
                        ..
                    },
                    ..
                },
                crate::execution::ResidentSegmentedAggregationStage {
                    operation: crate::execution::ResidentSegmentedAggregationOperation::Aggregate { .. },
                    ..
                },
                crate::execution::ResidentSegmentedAggregationStage {
                    operation: crate::execution::ResidentSegmentedAggregationOperation::Project { .. },
                    ..
                },
                crate::execution::ResidentSegmentedAggregationStage {
                    operation: crate::execution::ResidentSegmentedAggregationOperation::Order { .. },
                    ..
                },
                crate::execution::ResidentSegmentedAggregationStage {
                    operation: crate::execution::ResidentSegmentedAggregationOperation::Project { .. },
                    ..
                },
            ]
        ));
        assert_eq!(program.maximum_list_items, 2);
        assert_eq!(program.maximum_intermediate_rows, 4);
        assert_eq!(program.maximum_aggregate_input_rows()?, 4);

        let mut cpu = CpuBackend::new(32 * 1024 * 1024, 1024 * 1024);
        cpu.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let result =
            cpu.execute_segmented_aggregation(&compiled.request, &CancellationToken::new())?;
        let published = result.validate_for_publication(&compiled.request, BackendKind::Cpu)?;
        let relation = published.relation();
        assert_eq!((relation.row_count, relation.column_count), (2, 1));
        assert_eq!(
            relation
                .cells
                .iter()
                .map(|cell| (cell.tag, cell.payload as i64))
                .collect::<Vec<_>>(),
            [
                (ResidentSegmentedValueTag::Integer, 0),
                (ResidentSegmentedValueTag::Integer, 1),
            ]
        );
        assert_eq!(
            published
                .receipts()
                .iter()
                .map(|receipt| (receipt.input_cardinality, receipt.output_cardinality))
                .collect::<Vec<_>>(),
            [
                (1, 1),
                (1, 1),
                (1, 2),
                (2, 3),
                (3, 2),
                (3, 2),
                (2, 2),
                (2, 2),
                (2, 2),
            ]
        );
        assert!(published.graph_read_dependencies().is_empty());
        Ok(())
    }

    #[test]
    fn static_indexed_unwind_admission_is_proven_and_fail_closed() -> Result<()> {
        let graph = GraphStore::default();
        let tail = "UNWIND prows AS p \
                    UNWIND qrows[p] AS q \
                    WITH p, count(q) AS rng \
                    RETURN p ORDER BY rng";
        for query in [
            format!("WITH ['0'] AS prows, [[2]] AS qrows {tail}"),
            "WITH [0] AS prows, [[2]] AS qrows \
             UNWIND prows AS p UNWIND qrows[p + 0] AS q \
             WITH p, count(q) AS rng RETURN p ORDER BY rng"
                .to_owned(),
            "WITH null AS p, [[2]] AS qrows \
             UNWIND qrows[p] AS q WITH p, count(q) AS rng \
             RETURN p ORDER BY rng"
                .to_owned(),
            format!("WITH [null] AS prows, [[2]] AS qrows {tail}"),
        ] {
            assert!(
                compile_segmented_query(&query, &graph)?.is_none(),
                "unproven static index source was admitted: {query}"
            );
        }

        let exact = "WITH [0, 1] AS prows, [[2], [3, 4]] AS qrows \
                     UNWIND prows AS p UNWIND qrows[p] AS q \
                     WITH p, count(q) AS rng RETURN p ORDER BY rng";
        let physical = optimized_segmented_plan(exact, &graph, &BTreeMap::new())?;
        let compile = |physical: &crate::cypher::PhysicalPlan| {
            compile_segmented_aggregation(
                physical,
                ProjectId(uuid::Uuid::nil()),
                &graph,
                &BTreeMap::new(),
                Bookmark {
                    term: 0,
                    index: graph.revision(),
                },
                ResidentExecutionId { high: 17, low: 29 },
                64,
            )
        };
        let mut retained_scope = physical.clone();
        let crate::cypher::PhysicalOperator::Project { keep_scope, .. } =
            &mut retained_scope.operators[0]
        else {
            return Err(crate::Error::internal(
                "ReturnOrderBy4 [1] omitted its static projection",
            ));
        };
        *keep_scope = true;
        assert!(compile(&retained_scope)?.is_none());

        let mut duplicate_alias = physical;
        let crate::cypher::PhysicalOperator::Project { projection, .. } =
            &mut duplicate_alias.operators[0]
        else {
            unreachable!("shape checked above")
        };
        projection.items[1].alias = Some("prows".to_owned());
        assert!(compile(&duplicate_alias)?.is_none());
        Ok(())
    }

