    #[test]
    fn graph_aggregate_terminal_wildcard_expands_only_exact_visible_scope() -> Result<()> {
        let graph = GraphStore::default();
        let parameters = BTreeMap::new();
        let query = "MATCH (me: Person)--(you: Person) \
                     WITH me.age AS age, you \
                     WITH age, age + count(you.age) AS agg RETURN *";
        let compiled = compile_segmented_query(query, &graph)?.ok_or_else(|| {
            crate::Error::internal("With6 [6] terminal wildcard was not admitted")
        })?;
        assert_eq!(
            compiled
                .outputs
                .iter()
                .map(|output| output.name.as_str())
                .collect::<Vec<_>>(),
            ["age", "agg"]
        );
        let program = compiled.request.program.as_ref().ok_or_else(|| {
            crate::Error::internal("With6 [6] omitted its sealed segmented program")
        })?;
        assert!(matches!(
            program.stages.last(),
            Some(crate::execution::ResidentSegmentedAggregationStage {
                operation: crate::execution::ResidentSegmentedAggregationOperation::Project {
                    keep_scope: false,
                    bindings,
                },
                ..
            }) if bindings.len() == 2
        ));

        let physical = optimized_segmented_plan(query, &graph, &parameters)?;
        let compile = |plan: &crate::cypher::PhysicalPlan| {
            compile_segmented_aggregation(
                plan,
                ProjectId(uuid::Uuid::nil()),
                &graph,
                &parameters,
                Bookmark {
                    term: 0,
                    index: graph.revision(),
                },
                ResidentExecutionId { high: 17, low: 29 },
                64,
            )
        };

        let Some(crate::cypher::PhysicalOperator::Project { projection, .. }) =
            physical.operators.last()
        else {
            return Err(crate::Error::internal(
                "With6 [6] optimized plan lost its aggregate projection",
            ));
        };
        assert!(
            projection
                .items
                .iter()
                .all(|item| !matches!(item.expression, Expression::Star)),
            "complete terminal wildcard was not canonicalized to its aggregate scope"
        );

        let mut mixed = physical.clone();
        mixed
            .operators
            .push(crate::cypher::PhysicalOperator::Project {
                keep_scope: false,
                projection: crate::cypher::Projection {
                    distinct: false,
                    items: vec![
                        crate::cypher::ProjectionItem {
                            expression: Expression::Star,
                            alias: None,
                            source_text: None,
                        },
                        crate::cypher::ProjectionItem {
                            expression: Expression::Variable("age".to_owned()),
                            alias: None,
                            source_text: None,
                        },
                    ],
                },
            });
        assert!(
            compile(&mixed)?.is_none(),
            "mixed wildcard tail was admitted"
        );

        let mut aliased = physical;
        aliased
            .operators
            .push(crate::cypher::PhysicalOperator::Project {
                keep_scope: false,
                projection: crate::cypher::Projection {
                    distinct: false,
                    items: vec![crate::cypher::ProjectionItem {
                        expression: Expression::Star,
                        alias: Some("everything".to_owned()),
                        source_text: None,
                    }],
                },
            });
        assert!(
            compile(&aliased)?.is_none(),
            "aliased wildcard tail was admitted"
        );
        Ok(())
    }

    #[test]
    fn graph8_property_keys_distinct_is_sealed_and_executes_exact_cpu_semantics() -> Result<()> {
        const NODE_QUERY: &str = "MATCH (n) UNWIND keys(n) AS x RETURN DISTINCT x AS theProps";
        const OPTIONAL_NODE_QUERY: &str =
            "OPTIONAL MATCH (n) UNWIND keys(n) AS x RETURN DISTINCT x AS theProps";
        const RELATIONSHIP_QUERY: &str =
            "MATCH ()-[r:KNOWS]-() UNWIND keys(r) AS x RETURN DISTINCT x AS theProps";
        const OPTIONAL_RELATIONSHIP_QUERY: &str = "OPTIONAL MATCH ()-[r:KNOWS]-() \
             UNWIND keys(r) AS x RETURN DISTINCT x AS theProps";

        fn compile_keys(
            graph: &GraphStore,
            query: &str,
        ) -> Result<super::CompiledResidentSegmentedAggregationPlan> {
            let compiled = compile_segmented_query(query, graph)?.ok_or_else(|| {
                crate::Error::internal(format!(
                    "Graph8 property-keys query was not admitted: {query}"
                ))
            })?;
            assert_eq!(compiled.outputs.len(), 1);
            assert_eq!(compiled.outputs[0].name, "theProps");
            assert_eq!(compiled.request.input.row_count, 0);
            assert!(compiled.request.input.cells.is_empty());
            let program = compiled.request.program.as_ref().ok_or_else(|| {
                crate::Error::internal("Graph8 property-keys query omitted its sealed program")
            })?;
            assert!(matches!(
                program.source,
                crate::execution::ResidentSegmentedAggregationSource::GraphRelation { .. }
            ));
            let [keys, unwind, aggregate] = program.stages.as_slice() else {
                return Err(crate::Error::internal(
                    "Graph8 property-keys query changed its three-stage contract",
                ));
            };
            assert!(matches!(
                keys.operation,
                crate::execution::ResidentSegmentedAggregationOperation::PropertyKeys { .. }
            ));
            assert!(matches!(
                unwind.operation,
                crate::execution::ResidentSegmentedAggregationOperation::Unwind { .. }
            ));
            assert!(matches!(
                &aggregate.operation,
                crate::execution::ResidentSegmentedAggregationOperation::Aggregate {
                    groups,
                    reductions,
                } if groups.len() == 1
                    && matches!(reductions.as_slice(), [reduction]
                        if reduction.kind == crate::execution::ResidentSegmentedAggregateKind::CountAll
                            && reduction.input.is_none()
                            && !reduction.distinct)
            ));
            assert_eq!(program.outputs.len(), 1, "private count leaked publicly");
            assert_eq!(
                program.maximum_aggregate_input_rows()?,
                program.maximum_intermediate_rows as usize
            );
            Ok(compiled)
        }

        fn execute_compiled_keys(
            cpu: &CpuBackend,
            compiled: &super::CompiledResidentSegmentedAggregationPlan,
        ) -> Result<Vec<String>> {
            let result =
                cpu.execute_segmented_aggregation(&compiled.request, &CancellationToken::new())?;
            let published = result.validate_for_publication(&compiled.request, BackendKind::Cpu)?;
            assert_eq!(published.relation().column_count, 1);
            assert_eq!(
                published.graph_read_dependencies().len(),
                published.receipts()[0].output_cardinality as usize,
                "Graph8 source dependencies were not row-aligned and sealed"
            );
            let relation = published.relation();
            relation
                .cells
                .iter()
                .map(|cell| {
                    if cell.tag != ResidentSegmentedValueTag::String {
                        return Err(crate::Error::internal(
                            "Graph8 property-keys output was not a string",
                        ));
                    }
                    let start = usize::try_from(cell.payload).map_err(|_| {
                        crate::Error::internal("Graph8 key offset exceeds host addressability")
                    })?;
                    let length = usize::try_from(cell.auxiliary).map_err(|_| {
                        crate::Error::internal("Graph8 key length exceeds host addressability")
                    })?;
                    let end = start
                        .checked_add(length)
                        .ok_or_else(|| crate::Error::internal("Graph8 key byte range overflow"))?;
                    Ok(
                        std::str::from_utf8(relation.arena.get(start..end).ok_or_else(|| {
                            crate::Error::internal("Graph8 key byte range disappeared")
                        })?)
                        .map_err(|_| crate::Error::internal("Graph8 key was not UTF-8"))?
                        .to_owned(),
                    )
                })
                .collect()
        }

        fn execute_keys(graph: &GraphStore, query: &str) -> Result<BTreeSet<String>> {
            let compiled = compile_keys(graph, query)?;
            let mut cpu = CpuBackend::new(64 * 1024 * 1024, 8 * 1024 * 1024);
            cpu.admit_project(ResidentProjectImage::graph_only(Arc::new(
                graph.snapshot()?,
            )))?;
            Ok(execute_compiled_keys(&cpu, &compiled)?
                .into_iter()
                .collect())
        }

        let mut one_node = GraphStore::default();
        let name = one_node.catalog_mut().intern_property("name")?;
        let surname = one_node.catalog_mut().intern_property("surname")?;
        let null_property = one_node.catalog_mut().intern_property("missing")?;
        one_node.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: vec![
                (name, ScalarValue::String("Andres".into())),
                (surname, ScalarValue::String("Lopez".into())),
                (null_property, ScalarValue::Null),
            ],
        })?;
        assert_eq!(
            execute_keys(&one_node, NODE_QUERY)?,
            BTreeSet::from(["name".to_owned(), "surname".to_owned()]),
            "canonical NULL property was exposed by keys()"
        );

        let mut delta_graph = GraphStore::default();
        let zeta = delta_graph.catalog_mut().intern_property("zeta")?;
        let alpha = delta_graph.catalog_mut().intern_property("alpha")?;
        let removed = delta_graph.catalog_mut().intern_property("removed")?;
        assert!(
            zeta < alpha && alpha < removed,
            "test property IDs did not preserve insertion order"
        );
        let stable_node = NodeId(50_000);
        delta_graph.insert_node(NodeInput {
            id: stable_node,
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: vec![
                (zeta, ScalarValue::String("kept".into())),
                (removed, ScalarValue::String("old".into())),
            ],
        })?;
        let mut delta_cpu = CpuBackend::new(64 * 1024 * 1024, 8 * 1024 * 1024);
        delta_cpu.admit_project(ResidentProjectImage::graph_only(Arc::new(
            delta_graph.snapshot()?,
        )))?;
        delta_graph.set_node_property(stable_node, removed, ScalarValue::Null, 2)?;
        delta_graph.set_node_property(
            stable_node,
            alpha,
            ScalarValue::String("added".into()),
            3,
        )?;
        delta_cpu.apply_project_delta(ResidentProjectDelta {
            project: ProjectId(uuid::Uuid::nil()),
            bookmark: Bookmark { term: 0, index: 3 },
            graph: delta_graph.device_delta(3)?,
            temporal: Vec::new(),
            vectors: Vec::new(),
            invalidate_derived: true,
        })?;
        let delta_compiled = compile_keys(&delta_graph, NODE_QUERY)?;
        let delta_program = delta_compiled.request.program.as_ref().ok_or_else(|| {
            crate::Error::internal("delta property-keys query omitted its sealed program")
        })?;
        let crate::execution::ResidentSegmentedAggregationOperation::PropertyKeys {
            descriptors,
            ..
        } = &delta_program.stages[0].operation
        else {
            return Err(crate::Error::internal(
                "delta property-keys query lost its sealed transform",
            ));
        };
        assert_eq!(
            descriptors
                .iter()
                .map(|descriptor| (descriptor.property, descriptor.name.as_str()))
                .collect::<Vec<_>>(),
            [(zeta, "zeta"), (alpha, "alpha"), (removed, "removed")],
            "property-key descriptors were not sealed in PropertyId order"
        );
        assert_eq!(
            execute_compiled_keys(&delta_cpu, &delta_compiled)?
                .into_iter()
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(["alpha".to_owned(), "zeta".to_owned()]),
            "complete delta replacement did not add/remove keys through canonical NodeId mapping"
        );

        let mut multiple_nodes = GraphStore::default();
        let properties = ["name", "surname", "otherName", "otherSurname"]
            .into_iter()
            .map(|name| {
                multiple_nodes
                    .catalog_mut()
                    .intern_property(name)
                    .map(|property| (property, name))
            })
            .collect::<Result<Vec<_>>>()?;
        for (id, selected) in [(NodeId(1), &properties[..2]), (NodeId(2), &properties[2..])] {
            multiple_nodes.insert_node(NodeInput {
                id,
                layer: Layer::Observed,
                revision: id.0,
                labels: Vec::new(),
                properties: selected
                    .iter()
                    .map(|(property, value)| (*property, ScalarValue::String((*value).into())))
                    .collect(),
            })?;
        }
        assert_eq!(
            execute_keys(&multiple_nodes, NODE_QUERY)?,
            BTreeSet::from([
                "name".to_owned(),
                "surname".to_owned(),
                "otherName".to_owned(),
                "otherSurname".to_owned(),
            ])
        );

        let mut propertyless_node = GraphStore::default();
        propertyless_node.catalog_mut().intern_property("unused")?;
        propertyless_node.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: Vec::new(),
        })?;
        assert!(execute_keys(&propertyless_node, NODE_QUERY)?.is_empty());
        assert!(
            execute_keys(&propertyless_node, OPTIONAL_NODE_QUERY)?.is_empty(),
            "propertyless optional node did not unwind to zero rows"
        );

        let mut null_node = GraphStore::default();
        null_node.catalog_mut().intern_property("unused")?;
        assert!(
            execute_keys(&null_node, OPTIONAL_NODE_QUERY)?.is_empty(),
            "keys(null node) did not remain null through UNWIND"
        );

        fn relationship_graph(with_properties: bool) -> Result<GraphStore> {
            let mut graph = GraphStore::default();
            let knows = graph.catalog_mut().intern_relationship_type("KNOWS")?;
            let status = graph.catalog_mut().intern_property("status")?;
            let year = graph.catalog_mut().intern_property("year")?;
            for id in [NodeId(1), NodeId(2)] {
                graph.insert_node(NodeInput {
                    id,
                    layer: Layer::Observed,
                    revision: id.0,
                    labels: Vec::new(),
                    properties: Vec::new(),
                })?;
            }
            graph.insert_edge(EdgeInput {
                id: EdgeId(1),
                source: NodeId(1),
                target: NodeId(2),
                relationship_type: knows,
                layer: Layer::Observed,
                revision: 3,
                properties: if with_properties {
                    vec![
                        (status, ScalarValue::String("bad".into())),
                        (year, ScalarValue::String("2015".into())),
                    ]
                } else {
                    Vec::new()
                },
            })?;
            Ok(graph)
        }

        let relationship = relationship_graph(true)?;
        assert_eq!(
            execute_keys(&relationship, RELATIONSHIP_QUERY)?,
            BTreeSet::from(["status".to_owned(), "year".to_owned()])
        );
        let propertyless_relationship = relationship_graph(false)?;
        assert!(execute_keys(&propertyless_relationship, RELATIONSHIP_QUERY)?.is_empty());
        assert!(execute_keys(&propertyless_relationship, OPTIONAL_RELATIONSHIP_QUERY)?.is_empty());
        let mut no_relationship = GraphStore::default();
        no_relationship
            .catalog_mut()
            .intern_relationship_type("KNOWS")?;
        no_relationship.catalog_mut().intern_property("unused")?;
        for id in [NodeId(1), NodeId(2)] {
            no_relationship.insert_node(NodeInput {
                id,
                layer: Layer::Observed,
                revision: id.0,
                labels: Vec::new(),
                properties: Vec::new(),
            })?;
        }
        assert!(
            execute_keys(&no_relationship, OPTIONAL_RELATIONSHIP_QUERY)?.is_empty(),
            "erased optional relationship null extension leaked through UNWIND"
        );

        for query in [
            "MATCH (n) UNWIND keys(n) AS x RETURN x AS theProps",
            "MATCH (n) UNWIND keys(n) AS x WHERE x = 'name' RETURN DISTINCT x AS theProps",
            "MATCH (n) UNWIND keys(n) AS x RETURN DISTINCT x AS theProps, count(*) AS n",
            "MATCH (n) UNWIND labels(n) AS x RETURN DISTINCT x AS theProps",
            "MATCH ()-[r:KNOWS]->() UNWIND keys(r) AS x RETURN DISTINCT x AS theProps",
            "OPTIONAL MATCH ()-[r:KNOWS]-() UNWIND keys(r) AS x \
             RETURN DISTINCT x AS theProps, count(*) AS n",
        ] {
            assert!(
                compile_segmented_query(query, &one_node)?.is_none(),
                "neighboring property-keys shape entered the exact Graph8 route: {query}"
            );
        }
        Ok(())
    }

    #[test]
    fn return_orderby2_08_expands_wildcard_into_native_node_sort() -> Result<()> {
        let mut graph = GraphStore::default();
        let id = graph.catalog_mut().intern_property("id")?;
        for (node, value) in [(NodeId(1), 10), (NodeId(2), 1)] {
            graph.insert_node(NodeInput {
                id: node,
                layer: Layer::Observed,
                revision: node.0,
                labels: Vec::new(),
                properties: vec![(id, ScalarValue::Integer(value))],
            })?;
        }

        let compiled = compile_resident_query("MATCH (n) RETURN * ORDER BY n.id", &graph)?
            .ok_or_else(|| {
                crate::Error::internal("ReturnOrderBy2 [8] wildcard sort was not admitted")
            })?;
        assert!(compiled.grouping.is_none());
        assert!(compiled.temporal.is_none());
        assert!(matches!(
            compiled.outputs.as_slice(),
            [output]
                if output.name == "n"
                    && output.source
                        == super::ResidentOutputSource::Node(ResidentNodeBinding::Start)
        ));
        assert!(matches!(
            compiled.request.orders.as_slice(),
            [order]
                if order.binding == ResidentNodeBinding::Start
                    && order.property == id
                    && !order.descending
                    && !order.nulls_first
        ));
        assert!(
            compile_resident_query("MATCH (n) RETURN *, n.id", &graph)?.is_none(),
            "mixed wildcard projection was admitted without its own complete contract"
        );
        assert!(
            compile_resident_query("MATCH (a)-->(b) RETURN *", &graph)?.is_some(),
            "ordinary fixed-hop wildcard projection unexpectedly lost native admission"
        );
        assert!(
            compile_resident_query("MATCH p = (a)-->(b) RETURN *", &graph)?.is_none(),
            "wildcard projection admitted an unmaterialized named path and would omit `p`"
        );

        let mut backend = CpuBackend::new(32 * 1024 * 1024, 1024 * 1024);
        backend.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let resident =
            backend.execute_node_pipeline(&compiled.request, &CancellationToken::new())?;
        let ordered_ids = resident
            .start_rows
            .iter()
            .map(|dense| {
                graph
                    .node_dense(*dense)
                    .map(|node| node.id())
                    .ok_or_else(|| {
                        crate::Error::internal("native wildcard sort returned a stale row")
                    })
            })
            .collect::<Result<Vec<_>>>()?;
        assert_eq!(ordered_ids, [NodeId(2), NodeId(1)]);
        Ok(())
    }

    #[test]
    fn nullable_relationship_is_null_groups_and_counts_on_cpu_without_host_input() -> Result<()> {
        let mut graph = GraphStore::default();
        let player = graph.catalog_mut().intern_label("Player")?;
        let team = graph.catalog_mut().intern_label("Team")?;
        let plays_for = graph.catalog_mut().intern_relationship_type("PLAYS_FOR")?;
        let supports = graph.catalog_mut().intern_relationship_type("SUPPORTS")?;
        for (id, labels) in [
            (NodeId(1), vec![player]),
            (NodeId(2), vec![player]),
            (NodeId(3), vec![team]),
        ] {
            graph.insert_node(NodeInput {
                id,
                layer: Layer::Observed,
                revision: id.0,
                labels,
                properties: Vec::new(),
            })?;
        }
        for (id, source, relationship_type) in [
            (1, NodeId(1), plays_for),
            (2, NodeId(2), plays_for),
            (3, NodeId(1), supports),
            (4, NodeId(1), supports),
        ] {
            graph.insert_edge(EdgeInput {
                id: EdgeId(id),
                source,
                target: NodeId(3),
                relationship_type,
                layer: Layer::Observed,
                revision: 3 + id,
                properties: Vec::new(),
            })?;
        }
        let query = "MATCH (p:Player)-[:PLAYS_FOR]->(team:Team) \
                     OPTIONAL MATCH (p)-[s:SUPPORTS]->(team) \
                     RETURN count(*) AS matches, s IS NULL AS optMatch";
        let compiled = compile_segmented_query(query, &graph)?.ok_or_else(|| {
            crate::Error::internal("nullable relationship aggregation was not admitted")
        })?;
        let program = compiled.request.program.as_ref().ok_or_else(|| {
            crate::Error::internal("nullable relationship aggregation omitted its sealed program")
        })?;
        program.nullable_relationship_is_null_count()?;
        assert_eq!(compiled.request.input.row_count, 0);
        assert!(compiled.request.input.cells.is_empty());

        let mut cpu = CpuBackend::new(64 * 1024 * 1024, 8 * 1024 * 1024);
        cpu.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let result =
            cpu.execute_segmented_aggregation(&compiled.request, &CancellationToken::new())?;
        let published = result.validate_for_publication(&compiled.request, BackendKind::Cpu)?;
        let relation = published.relation();
        assert_eq!(relation.row_count, 2);
        assert_eq!(relation.column_count, 2);
        assert_eq!(relation.cells[0].tag, ResidentSegmentedValueTag::Integer);
        assert_eq!(relation.cells[0].payload as i64, 2);
        assert_eq!(relation.cells[1].tag, ResidentSegmentedValueTag::Boolean);
        assert_eq!(relation.cells[1].payload, 0);
        assert_eq!(relation.cells[2].tag, ResidentSegmentedValueTag::Integer);
        assert_eq!(relation.cells[2].payload as i64, 1);
        assert_eq!(relation.cells[3].tag, ResidentSegmentedValueTag::Boolean);
        assert_eq!(relation.cells[3].payload, 1);
        Ok(())
    }

    fn pattern_filter_expression(query: &str, catalog: &NameCatalog) -> Result<Expression> {
        let query = crate::cypher::parse(query)?;
        let bound = crate::cypher::bind(query, catalog, BindCapabilities::default())?;
        let plan = crate::cypher::plan(bound)?;
        plan.operators
            .iter()
            .find_map(|operator| match operator {
                crate::cypher::PhysicalOperator::Filter(expression) => Some(expression.clone()),
                _ => None,
            })
            .ok_or_else(|| crate::Error::internal("Pattern1 plan omitted its filter"))
    }

    fn compile_pattern_expression(
        expression: &Expression,
        catalog: &NameCatalog,
    ) -> Result<Option<super::CompiledResidentPatternPredicateProgram>> {
        compile_pattern_predicate_expression(
            expression,
            "n",
            catalog,
            ResidentExecutionId { high: 11, low: 29 },
            100,
        )
    }

    fn compile_pattern_query(
        query: &str,
        catalog: &NameCatalog,
    ) -> Result<Option<super::CompiledResidentPatternPredicateProgram>> {
        let expression = pattern_filter_expression(query, catalog)?;
        compile_pattern_expression(&expression, catalog)
    }

    fn existential_shape(
        query: &str,
        catalog: &NameCatalog,
    ) -> Result<Option<super::ResidentExistentialPredicateShape>> {
        let expression = pattern_filter_expression(query, catalog)?;
        let Expression::ExistentialSubquery(subquery) = expression else {
            return Err(crate::Error::internal(
                "existential test query omitted its typed subquery expression",
            ));
        };
        Ok(super::resident_existential_predicate_shape(
            &subquery, "n", catalog,
        ))
    }

    fn compile_pattern_pair_query(
        query: &str,
        catalog: &NameCatalog,
    ) -> Result<Option<super::CompiledResidentPatternPairPredicateProgram>> {
        let query = crate::cypher::parse(query)?;
        let bound = crate::cypher::bind(query, catalog, BindCapabilities::default())?;
        let mut plan = crate::cypher::plan(bound)?;
        for operator in &mut plan.operators {
            if let crate::cypher::PhysicalOperator::ScanPattern { access, .. } = operator {
                *access = ScanAccessPath::AllNodes;
            }
        }
        if plan.operators.len() != 4 {
            return Ok(None);
        }
        compile_pattern_pair_predicate_components(
            &plan.operators[0],
            &plan.operators[1],
            &plan.operators[2],
            &plan.operators[3],
            catalog,
            ResidentExecutionId { high: 89, low: 144 },
            200,
        )
    }

    #[test]
    fn return4_06_counts_distinct_directed_named_paths_as_relationship_identities() -> Result<()> {
        // Exact openCypher Return4 [6] fixture: one isolated node means the directed pattern has
        // no rows and the distinct path count is zero. The important proof is that the compiler
        // emits the existing native distinct-relationship aggregate instead of rejecting the
        // semantically irrelevant path name or materializing path values on the host.
        let mut graph = GraphStore::default();
        graph.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: Vec::new(),
        })?;
        let compiled =
            compile_resident_query("MATCH p = (n)-->(b) RETURN coUnt( dIstInct p )", &graph)?
                .ok_or_else(|| crate::Error::internal("Return4 [6] named path was not admitted"))?;
        let grouping = compiled
            .grouping
            .as_ref()
            .ok_or_else(|| crate::Error::internal("Return4 [6] omitted native grouping"))?;
        assert!(grouping.distinct_relationship);
        assert_eq!(grouping.aggregate, ResidentAggregate::CountAll);
        assert_eq!(grouping.key, None);
        assert_eq!(grouping.value, None);
        assert_eq!(
            grouping
                .input
                .expansion
                .as_ref()
                .map(|expansion| expansion.direction),
            Some(ResidentDirection::Outgoing)
        );
        assert!(matches!(
            compiled.outputs.as_slice(),
            [output] if output.source == super::ResidentOutputSource::GroupAggregate(0)
        ));

        let mut backend = CpuBackend::new(32 * 1024 * 1024, 1024 * 1024);
        backend.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let groups = backend.execute_node_group_pipeline(grouping, &CancellationToken::new())?;
        assert_eq!(groups.len(), 1);
        assert_eq!(groups[0].rows, 0);
        assert_eq!(groups[0].value, Some(ScalarValue::Integer(0)));
        Ok(())
    }

