    #[test]
    fn multiple_global_integer_reductions_share_the_resident_group_shape() -> Result<()> {
        let mut graph = GraphStore::default();
        let label = graph.catalog_mut().intern_label("Node")?;
        let property = graph.catalog_mut().intern_property("value")?;
        for (id, value) in [(1_u64, 9_i64), (2, -4), (3, 17)] {
            graph.insert_node(NodeInput {
                id: NodeId(id),
                layer: Layer::Observed,
                revision: id,
                labels: vec![label],
                properties: vec![(property, ScalarValue::Integer(value))],
            })?;
        }
        let compiled =
            compile_resident_query("MATCH (n:Node) RETURN min(n.value), max(n.value)", &graph)?
                .ok_or_else(|| {
                    crate::Error::internal("multi-reduction grouping was not admitted")
                })?;
        let minimum = compiled
            .grouping
            .as_ref()
            .ok_or_else(|| crate::Error::internal("minimum grouping is absent"))?;
        let [maximum] = compiled.additional_groupings.as_slice() else {
            return Err(crate::Error::internal(
                "maximum grouping was not compiled exactly once",
            ));
        };
        assert_eq!(minimum.aggregate, ResidentAggregate::Minimum);
        assert_eq!(maximum.aggregate, ResidentAggregate::Maximum);
        assert_eq!(minimum.value, maximum.value);
        assert_eq!(minimum.key, maximum.key);
        assert_eq!(
            compiled
                .outputs
                .iter()
                .map(|output| output.source)
                .collect::<Vec<_>>(),
            vec![
                super::ResidentOutputSource::GroupAggregate(0),
                super::ResidentOutputSource::GroupAggregate(1),
            ]
        );

        let mut backend = CpuBackend::new(32 * 1024 * 1024, 1024 * 1024);
        backend.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let minimum = backend.execute_node_group_pipeline(minimum, &CancellationToken::new())?;
        let maximum = backend.execute_node_group_pipeline(maximum, &CancellationToken::new())?;
        assert_eq!(minimum[0].value, Some(ScalarValue::Integer(-4)));
        assert_eq!(maximum[0].value, Some(ScalarValue::Integer(17)));
        Ok(())
    }

    #[test]
    fn comparison1_04_collapses_node_identity_self_join_to_native_count() -> Result<()> {
        // Exact openCypher Comparison1 [4] fixture and query. Equality over two scans of the same
        // bare node domain leaves one pair per node identity, so the retained native scan owns the
        // cardinality and the backend computes the count.
        let mut graph = GraphStore::default();
        graph.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: Vec::new(),
        })?;
        let compiled = compile_resident_query(
            "MATCH (a) WITH a MATCH (b) WHERE a = b RETURN count(b)",
            &graph,
        )?
        .ok_or_else(|| crate::Error::internal("Comparison1 [4] identity count was not admitted"))?;
        let grouping = compiled
            .grouping
            .as_ref()
            .ok_or_else(|| crate::Error::internal("Comparison1 [4] omitted native grouping"))?;
        assert!(grouping.input.expansion.is_none());
        assert_eq!(grouping.aggregate, ResidentAggregate::CountAll);
        assert_eq!(grouping.key, None);
        assert_eq!(grouping.value, None);
        assert!(!grouping.distinct_relationship);
        assert_eq!(compiled.outputs[0].name, "count(b)");

        let mut backend = CpuBackend::new(32 * 1024 * 1024, 1024 * 1024);
        backend.admit_project(ResidentProjectImage::graph_only(Arc::new(
            graph.snapshot()?,
        )))?;
        let groups = backend.execute_node_group_pipeline(grouping, &CancellationToken::new())?;
        assert_eq!(groups.len(), 1);
        assert_eq!(groups[0].rows, 1);
        assert_eq!(groups[0].value, Some(ScalarValue::Integer(1)));
        Ok(())
    }

